#!/bin/bash
# ================================================================
#  install_cpanel.sh - Hosting Da Vinci GT
#  Universidad Da Vinci de Guatemala - Redes de Datos 1
#
#  Instala:
#    - 5 paginas HTML tematicas (CloudNova, InfraTech,
#      DataSphere, NexusHost, TechIDE)
#    - cPanel PHP con Editor HTML, Gestor Archivos,
#      Mi Sitio, Servicios
#    - Apache con Symlinks (metodo confirmado)
#
#  REQUISITO: Ejecutar setup_hosting.sh primero
#  Uso: sudo bash install_cpanel.sh
# ================================================================
set -e
GR='\033[0;32m'; BL='\033[0;34m'; YL='\033[1;33m'; NC='\033[0m'
log()  { echo -e "${GR}[OK]${NC} $1"; }
info() { echo -e "${BL}[..]${NC} $1"; }
warn() { echo -e "${YL}[!!]${NC} $1"; }
[ "$EUID" -ne 0 ] && echo "ERROR: sudo bash install_cpanel.sh" && exit 1

echo ""
echo "================================================================"
echo "  install_cpanel.sh - Da Vinci GT"
echo "  IP: 4.205.13.148"
echo "================================================================"
echo ""

# ── 1. Paginas HTML de los 5 sitios (base64) ─────────────────────
info "Instalando paginas HTML..."
for F in cloudnova infratech datasphere nexushost techide; do
    mkdir -p /var/www/$F/public_html /var/www/$F/logs
    chown -R www-data:www-data /var/www/$F/
    chmod -R 777 /var/www/$F/
done

echo ""  | base64 -d > /var/www/cloudnova/public_html/index.html
log "CloudNova  -> http://4.205.13.148/cloudnova/"

echo ""  | base64 -d > /var/www/infratech/public_html/index.html
log "InfraTech  -> http://4.205.13.148/infratech/"

echo "" | base64 -d > /var/www/datasphere/public_html/index.html
log "DataSphere -> http://4.205.13.148/datasphere/"

echo ""  | base64 -d > /var/www/nexushost/public_html/index.html
log "NexusHost  -> http://4.205.13.148/nexushost/"

echo ""    | base64 -d > /var/www/techide/public_html/index.html
log "TechIDE    -> http://4.205.13.148/techide/"

for F in cloudnova infratech datasphere nexushost techide; do
    chmod 666 /var/www/$F/public_html/index.html
    chown www-data:www-data /var/www/$F/public_html/index.html
done

# ── 2. Apache con Symlinks ───────────────────────────────────────
info "Configurando Apache con symlinks..."
for SITE in $(ls /etc/apache2/sites-enabled/ 2>/dev/null); do
    a2dissite "$SITE" 2>/dev/null || true
done
rm -f /var/www/html/index.html

echo "" | base64 -d > /etc/apache2/sites-available/000-cpanel.conf

# Symlinks: unico metodo que funciona en esta VM
ln -sfn /var/www/cloudnova/public_html  /var/www/html/cloudnova
ln -sfn /var/www/infratech/public_html  /var/www/html/infratech
ln -sfn /var/www/datasphere/public_html /var/www/html/datasphere
ln -sfn /var/www/nexushost/public_html  /var/www/html/nexushost
ln -sfn /var/www/techide/public_html    /var/www/html/techide

a2ensite 000-cpanel 2>/dev/null || true
apache2ctl configtest 2>&1 | tail -1
log "Apache configurado con symlinks"

# ── 3. cPanel PHP con Editor HTML (base64) ───────────────────────
info "Instalando cPanel con Editor HTML..."
echo "" | base64 -d > /var/www/html/index.php
chown www-data:www-data /var/www/html/index.php
chmod 644 /var/www/html/index.php
php -l /var/www/html/index.php 2>&1 | grep -i "error" && warn "Revisar PHP syntax" || log "cPanel PHP syntax OK"
grep -q "Editor HTML" /var/www/html/index.php && log "Editor HTML incluido" || warn "Editor HTML no encontrado"

# ── 4. Permisos finales ──────────────────────────────────────────
info "Aplicando permisos finales..."
for F in cloudnova infratech datasphere nexushost techide; do
    chown -R www-data:www-data /var/www/$F/
    chmod -R 777 /var/www/$F/public_html
done
systemctl restart apache2
log "Apache reiniciado"

# ── 5. Verificacion automatica ───────────────────────────────────
echo ""; info "Verificando sitios..."
ALL_OK=true
for F in cloudnova infratech datasphere nexushost techide; do
    CODE=$(curl -s -o /dev/null -w "%{http_code}" http://localhost/$F/ 2>/dev/null || echo 0)
    SZ=$(wc -c < /var/www/$F/public_html/index.html 2>/dev/null || echo 0)
    if [ "$CODE" = "200" ]; then
        log "http://4.205.13.148/$F/ ($SZ bytes)"
    else
        warn "http://4.205.13.148/$F/ ERROR HTTP $CODE"
        ALL_OK=false
    fi
done

echo ""
echo "================================================================"
echo "  INSTALACION COMPLETA"
echo ""
echo "  cPanel:    http://4.205.13.148"
echo ""
echo "  URL                              Sitio       Usuario"
echo "  http://4.205.13.148/cloudnova/   CloudNova   eamperez"
echo "  http://4.205.13.148/infratech/   InfraTech   gjuarez"
echo "  http://4.205.13.148/datasphere/  DataSphere  cpatricio"
echo "  http://4.205.13.148/nexushost/   NexusHost   fcalderon"
echo "  http://4.205.13.148/techide/     TechIDE     crodas"
echo ""
echo "  CREDENCIALES:"
echo "  eamperez  / Emp@2024#Sec1"
echo "  gjuarez   / Jua%2024#Net2"
echo "  cpatricio / Pat!2024#Sys3"
echo "  fcalderon / Cal*2024#Dev4"
echo "  crodas    / Rod#2024@Tech5"
echo ""
echo "  CPANEL INCLUYE:"
echo "  - Login limpio (sin tabla)"
echo "  - Dashboard con accesos rapidos"
echo "  - Gestor de Archivos"
echo "  - Editor HTML con preview en vivo"
echo "  - Mi Sitio con iframe + boton Abrir"
echo "  - Servicios con tabla de todos los sitios"
echo "================================================================"
